mapper.select:
select tti.seq_no as seqNo, /*流水号*/ tti.sch_id as schId, /*方案代码*/
a.assetId as assetId, /*资产代码*/ a.assetName as assetName, /*资产名称*/ a.finprodType as finprodType, /*金融产品分类*/ tti.asset_classify as assetClassify, /*资产分类*/ tti.capi_income_feature as capiIncomeFeature, /*本金收益特征*/ tti.income_type as incomeType, /*收入类型*/ tti.taxable_sign as taxableSign, /*计税方式 - 应税标识*/ tti.tax_rate*100 as taxRate, /*应税税率*/ TO_CHAR(tti.eff_date, 'yyyy-MM-dd') as effDate, /*生效日*/ tti.maintenance_mode as maintenanceMode, /*维护方式*/ tti.fee_type as feeType /*免税收入类型*/ from TAX_TAXABLE_INFO tti inner join (
select nvl(fp.finprod_market_id, fp.finprod_id) as assetId, /*资产代码*/ nvl(fp.finprod_abbr, fp.finprod_name) as assetName, /*资产名称*/ fp.finprod_type as finprodType, /*金融产品分类*/ fp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, /*资产代码*/ ftp.finprod_id as assetName, /*资产名称*/ ftp.finprod_type as finprodType, /*金融产品分类*/ ftp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
) a on a.originalFinprodId = tti.asset_id /**数据库中已改为存资产代码，不是市场代码**/ where tti.seq_no = #{seqNo,jdbcType=VARCHAR}

select * from (
select nvl(fp.finprod_market_id, fp.finprod_id) as assetId, /*资产代码*/ nvl(fp.finprod_abbr, fp.finprod_name) as assetName, /*资产名称*/ fp.finprod_type as finprodType, /*金融产品分类*/ fp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id left join fin_product_add fpd on fp.finprod_id = fpd.finprod_id where fpt.type_3 is not null and fpd.appear_market_id is null
union all
select ftp.finprod_id as assetId, /*资产代码*/ ftp.finprod_id as assetName, /*资产名称*/ ftp.finprod_type as finprodType, /*金融产品分类*/ ftp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id left join fin_product_add fpd on ftp.finprod_id = fpd.finprod_id where fpt.type_3 is not null and ftp.branch = '0' and fpd.appear_market_id is null
)t
/*标的中部分标的需要数据隔离，无法使用共通配置数据隔离，这里手动进行数据隔离*/ 1=1
AND NOT EXISTS( SELECT * FROM DATA_AUTH_NOTIFY_INST DANI99 WHERE DANI99.INSTITUTION_CODE NOT IN
#{item}
AND T.ORIGINALFINPRODID = DANI99.BUSINESS_ID AND DANI99.MODEL_TYPE = '02' )
AND (assetId like '%' || #{search} || '%' OR assetName like '%' || #{search} || '%' )

select * from (
select nvl(fp.finprod_market_id, fp.finprod_id) as assetId, /*资产代码*/ nvl(fp.finprod_abbr, fp.finprod_name) as assetName, /*资产名称*/ fp.capi_income_feature as capiIncomeFeature, /*本金收益特征*/ fpt.type_3 as assetClassify, /*资产分类*/ fp.finprod_type as finprodType, /*金融产品分类*/ fp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_product fp on fp.finprod_id = fpt.finprod_id where fpt.type_3 is not null
union all
select ftp.finprod_id as assetId, /*资产代码*/ ftp.finprod_id as assetName, /*资产名称*/ ftp.capi_income_feature as capiIncomeFeature, /*本金收益特征*/ fpt.type_3 as assetClassify, /*资产分类*/ ftp.finprod_type as finprodType, /*金融产品分类*/ ftp.finprod_id as originalFinprodId /*资产代码*/ from fin_product_type fpt inner join fin_trade_product ftp on ftp.finprod_id = fpt.finprod_id where fpt.type_3 is not null and ftp.branch = '0'
)
where assetId = #{assetId} and finprodType = #{finprodType}
